commands:
d=$(mktemp -d); mkdir -p "$d/realdir"; ln -s /nonexistent/gone "$d/dangling"; printf x > "$d/real"; : > "$d/empty"; printf y > "$d/realdir/inside"; ln -s real "$d/goodlink"; ln -s realdir "$d/dirlink";
echo "=== ls -lL combined ==="; ls -lL "$d/real" "$d/empty" "$d/dangling" "$d/goodlink" "$d/dirlink" "$d/realdir" "$d/ghost" 2>&1;
echo "=== ls -lL dir (GNU: dropped or message?) ==="; ls -lL "$d" 2>&1;
echo "=== ls -l dir ==="; ls -l "$d" 2>&1;
ls --version | head -1; rm -rf "$d"
